script.setup:
const s=ctx.state,gl=ctx.gl;
s.program=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,"#version 300 es
precision highp float;
#define GLSLIFY 1
in vec2 v_uv;out vec4 outColor;uniform vec2 u_resolution;uniform sampler2D u_image;
uniform float u_scale;
uniform float u_seed;
highp float random(vec2 co)
{
    highp float a = 12.9898;
    highp float b = 78.233;
    highp float c = 43758.5453;
    highp float dt= dot(co.xy ,vec2(a,b));
    highp float sn= mod(dt,3.14);
    return fract(sin(sn) * c);
}

void main(){vec2 uv=v_uv,p=(uv*2.-1.)*u_resolution/min(u_resolution.x,u_resolution.y);vec3 color;vec2 cell=floor(uv*u_scale);float r=random(cell+u_seed);color=mix(vec3(.04,.1,.18),vec3(.96,.65,.4),r);vec2 f=fract(uv*u_scale);color*=smoothstep(0.,.07,min(min(f.x,f.y),min(1.-f.x,1.-f.y)));
outColor=vec4(color,1);}");
